tool_input.command:
mkdir -p /tmp/scratch && cat > /tmp/scratch/T.java <<'EOF'
import org.apache.commons.csv.*;
import java.util.*;
public class T {
    public static void main(String[] a) throws Exception {
        CSVParser p = CSVParser.parse("\"a\"b,c\n", CSVFormat.DEFAULT.withQuoteChar('"'));
        List<CSVRecord> recs = p.getRecords();
        for (CSVRecord r : recs) {
            for (String s : r) System.out.println("["+s+"]");
            System.out.println("---");
        }
    }
}
EOF
javac -cp target/classes -d /tmp/scratch /tmp/scratch/T.java && java -cp target/classes:/tmp/scratch T
